head.script:
scwin.trigger1_onclick = function(e) {
    editor1.setDisabled(true);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 'disabled'버튼을 클릭한다.
    //1. Run the sample file and click the 'disabled' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    // verify step 1. eidtor가 disabled되어 보여진다.
    //1. eidtor is disabled. 
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#editor1_disabled_div').length > 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Mar-2018
    //end unitTest
}
